#!/usr/bin/env python3
"""Prepare auditable scene/UI prompts. Artwork is generated by native imagegen."""
from pathlib import Path
import json
scenes={s['id']:{'path':str(f),**s} for f in Path('game/content/chapters').glob('*.json') for s in json.loads(f.read_text()).get('scenes',[])}
items=[
 ('wucheng-street-evening','梧城雨后街头',['after_school_choice'],'19:16的现代中国江城普通街头，刚入夜的老街十字路口，雨后湿路、公交站棚、居民楼空调外机、共享单车和暖色小店灯，远处有人生活的城市气息但不画可辨识人物，前景人行道开阔。不是学校大门。'),
 ('municipal-archive-basement','市档案馆地下库',['c4_tinglan_1'],'14:05，市档案馆地下文献库，无大窗，混凝土地面、密集移动式金属档案架、泛黄档案盒、除湿机、顶面管线、白色荧光灯，留出宽通道与一张阅档小桌，干燥纸张与旧建筑的年代感。不是学校图书馆。'),
 ('archive-rooftop-evening','市档案馆楼顶',['c4_tinglan_2'],'17:30，市档案馆行政办公楼楼顶，老城区灰色行政建筑、暖色天光和远处江城天际线，水泥女儿墙、安全铁栏、通风管和水箱，几张无字档案纸压在矮桌上，平静而悬而未决。不是学校天台。'),
 ('abandoned-station-entrance','废弃站口',['c4_tangli_2'],'17:02，城市边缘一座封闭废弃地铁站入口，半落卷帘门、锈蚀护栏、通向地下的湿台阶、杂草、施工围挡、积水、褪色但不可读的指示牌，阴天傍晚自然光，站外视角，带现实生活的荒置感。不是运营中的站台。'),
 ('information-lab','梧城一中信息教室',['c4_nanxing_1'],'15:44，中国公立高中信息技术教室，成排普通台式电脑与关闭或暗色空屏、网线、教师桌、校园机房交换柜、白板与窗外绿树，午后柔和自然光，干净克制、有人刚离开。没有画架、颜料或美术教室装饰。'),
 ('chendu-home-morning','陈渡家清晨',['chapter5_gate'],'06:00，陈渡与夜班护士母亲住的普通中国城市小户型家，卧室通向小客厅，书桌、床边手机、晾衣架、桌上的饭盒和保温杯，窗外灰蓝晨光，普通温暖生活，前景有进出门的空间。不画人物，不画精装豪宅。'),
 ('city-desync-afternoon','梧城市区错位',['c5_city_desync'],'14:26，现代中国梧城市区十字路口，正常午后街道与夜梧城开始重叠：楼体边缘出现轻微错位双影，一部分路面是白天干燥光、一部分反射夜雨的冷蓝光，公交站和普通店铺仍可辨认，恐惧来自生活秩序错位，不画赛博城市或魔法传送门。'),
 ('north-station-control','梧城北站控制室',['c5_anchor_truth'],'18:31，梧城北站运营控制室室内，老式综合控制台、轨道示意监视屏（仅无字示意线）、值班日志纸、对讲机、普通办公椅、墙上监视器，透过小窗可见暮色站台，顶灯冷白、细微紫蓝失真，真实铁路运营空间，不是科幻飞船。'),
 ('night-school-corridor','夜梧城旧教学楼走廊',['c6_echo_goodbye'],'18:42之后的夜梧城旧教学楼内部走廊，中国旧高中建筑，空教室门、磨旧水磨石地面、蓝灰窗光、尽头一盏普通灯、轻微重复门框错位像失败读档的残响正在退去，幽静克制，无怪物无血腥，前景通道开阔。'),
 ('night-school-exit','夜梧城旧教学楼出口',['c6_last_door'],'未知时间的夜梧城旧教学楼门口，从楼内看一扇半开的普通旧玻璃门，门外雨后小院和一条通往现实的路，室内冷蓝、外面微暖自然天光，门框、地垫、旧墙角清晰，象征走出存档但不画任何按钮、文字或魔法大门。'),
 ('night-nanhu-station','夜梧城南湖站',['c4_xuqi_1'],'18:42的夜梧城南湖地铁站，地下站台、黄线、普通站台屏蔽门、长椅和柱子，空无一人，顶灯冷白、远端灯光轻微蓝紫错位，列车窗映出重复的空间残影，普通地铁的异常副本，不是室外铁路站。所有屏幕暗色不含可读文字。'),
 ('night-clocktower','夜梧城钟楼下',['c4_xuqi_2','end_xuqi'],'永远18:42的夜梧城钟楼街口，老式砖石钟楼、空无行人的普通中国城市老街、亮着的店铺橱窗、共享单车静止、湿路面和微弱紫蓝边缘失真。钟盘仅画指针约六点四十二、无需数字文字。冷蓝低饱和，不能画霓虹赛博朋克。'),
 ('river-levee-evening','城外江堤',['end_tangli'],'10月24日18:43的城外江堤，红灰跑步道延伸向远处，江面、芦苇、堤坡草地、简单路灯和远处桥梁，雨后仍有小片积水，傍晚柔和自然余晖，开阔清爽、有继续向前的感觉。不是市中心石栏杆江滩广场。'),
 ('municipal-archive-workroom','市档案馆修复工作室',['end_tinglan'],'10月24日18:43的市档案馆文献修复工作室，宽阔实木工作桌、素白空纸、修复刷、棉手套、纸张托盘、档案柜与暖色台灯，窗外自然傍晚，旧纸质感和真实工作秩序；没有人物，前景留一张可坐下交谈的桌子。'),
 ('nanhu-station-exit','南湖站出口',['station_refuse'],'19:31的现实梧城南湖站出口，站内通向街面的普通地铁通道与上行台阶，黄白灯光、扶手、疏散通道、半闭临时隔离栏，外面是雨夜街口，空间布局可信，所有告示不含可读文字，不能画站台轨道。'),
 ('information-rooftop-evening','信息楼天台',['c4_nanxing_2','end_nanxing'],'18:10至18:43的梧城一中信息楼天台，与普通学校天台有所区别：小型通信天线、线路盒、设备管道、安全护栏、远处教学楼和居民楼，夕阳暖光与灰蓝阴影，前景有可倚靠的水泥矮墙，生活化而非科幻。'),
 ('old-art-room-evening','旧美术教室夜间',['focus_xiaoman_open','route_convergence'],'19:10之后的现实梧城一中旧美术教室，与白天同样的中国旧教学楼房间，木桌、画架、石膏像、颜料盒、画纸和社团海报草稿无字，窗外已入夜，室内普通日光灯与一盏暖台灯，正常世界没有异常裂纹和紫光，没有人物。'),
 ('underpass-exit-evening','下穿通道出口',['breakthrough_first'],'18:47，雨夜下穿通道出口，视角从湿暗的瓷砖步道往上行台阶与雨后的江滩步道看，扶手、排水沟、路灯、积水与远处普通城市桥灯，自然现实世界重新恢复，蓝灰夜色中一盏暖光，不能只有江面或没有通道的风景。'),
 ('north-station-after1842','北站时间向前',['c6_walk_forward'],'18:43，不可逆之后的梧城北站站台，沿用中国老式室外铁路站：混凝土雨棚、钢轨、架空线、长椅、湿地面、冷白站灯，暮色稍放晴，数字钟留暗屏由游戏表达时间，不再固定18:42，远处有可离开的普通出站通道，无人物。'),
 ('north-station-vanishing','正在消失的北站',['c6_escape'],'18:47，正在消失的梧城北站，真实中国旧铁路站台的雨棚、架空线和远端月台正逐渐变成半透明蓝灰轮廓与光尘，前景地面和出口仍清晰可走，湿路反光，异常是空间退去而非爆炸，无赛博UI、无文字无人物。')]
base='Use case: illustration-story\nAsset type: RESET visual novel background\n正式横幅16:9场景背景，现代中国江城/校园都市灵异VN，精细二维动画背景画，清晰可信透视，细腻手绘线条与克制渐变，低饱和自然色、不过量逆光、背景略写实但不摄影不3D不厚涂。镜头为人物对话所处的人眼高度，中下部有清晰地面与宽阔空间，中央站位区不被大件前景遮挡，手机中央裁切也能辨认地点。无可辨认人物、无文字、无水印、无logo、无游戏UI。'
planpath=Path('game/visual/r8-native-art-production.json');plan=json.loads(planpath.read_text());plan['backgrounds']=[];mapping=[]
for id,name,ids,design in items:
 d=Path('game/art-sources/chatgpt/backgrounds')/id;d.mkdir(parents=True,exist_ok=True)
 (d/'prompt.txt').write_text(base+'\nScene/backdrop: '+design+'\n')
 evidence=[{'scene':i,'path':scenes[i]['path'],'location':scenes[i].get('location'),'time':scenes[i].get('time'),'previousBackground':scenes[i].get('background'),'sampleLines':[{'id':l.get('id'),'text':l.get('text')} for l in scenes[i].get('lines',[])[:2]]} for i in ids]
 (d/'spec.json').write_text(json.dumps({'schema':1,'id':id,'name':name,'kind':'background','sourceCommit':'8d190ebec6fb8c91b2f6c984bd6010b1d4de6005','canonSources':['docs/ART_DIRECTION.md',*[e['path'] for e in evidence]],'sceneEvidence':evidence,'designProposal':design,'reviewStatus':'UNVERIFIED','native4kClaim':False},ensure_ascii=False,indent=2)+'\n')
 plan['backgrounds'].append({'id':id,'name':name,'kind':'background','status':'TO_GENERATE','scenes':ids,'prompt':str(d/'prompt.txt'),'spec':str(d/'spec.json')})
 mapping.extend({'scene':i,'previousBackground':scenes[i].get('background'),'background':id} for i in ids)
Path('game/visual/r8-scene-background-plan.json').write_text(json.dumps({'schema':1,'reason':'Replace mismatched location/time reuse with dedicated native background candidates; preserve Scene and Line IDs.','mappings':mapping},ensure_ascii=False,indent=2)+'\n')
uis=[
 ('title-key-visual','标题页主视觉','现代中国梧城雨夜的十字路口和远处旧教学楼，湿路面映出一盏冷白街灯，建筑玻璃里出现一层微弱错位倒影，远处普通钟楼仅作轮廓，蓝灰和少量暖色。中央55%保持低细节、较暗留白供真实标题菜单叠加。不要人物、不要钟面数字。'),
 ('save-anomaly','存档异常主视觉','一间无人的旧教室在窗玻璃中重复成几层若隐若现的空间，桌上一只合着的普通记录本与细微错位光影，冷蓝灰加少许暗紫，安静不安。作为存读档页面的背景横幅，中间横向带留白，不能画虚假的存档按钮、文字、警告符号或矩形卡片UI。'),
 ('ending-collection-header','结局收藏主视觉','一间雨后明亮的空教室，六把普通木椅围在一张宽桌旁，窗边一只空的旧木相框象征未被归档的第七人，柔和青灰色自然光和纸张记忆气氛，平静留白，主体在横向中部，适合裁成页面顶部横幅。没有人物、没有可读文字、没有UI。'),
 ('cg-gallery-header','CG画廊主视觉','木桌上几张无人物的普通梧城风景相片错落：雨夜站台、学校天台、江滩、旧教室；旧相框和一小束窗光，冷灰蓝低饱和，像整理幸存的记忆，画面中心横带清楚，两端留白，适合作为CG收藏页顶部横幅。没有文字、没有UI、不要复制任何角色脸。'),
 ('combat-hud-key-visual','战斗页面主视觉','空无一人的雨夜下穿通道，湿瓷砖、排水沟、冷白灯，水面倒影与建筑错开半拍，左右两端有微弱层叠的蓝灰空间残响，中央大面积暗色留白供真实战斗信息与按键显示。只是原画背景，禁止画准星、血条、按钮、数字、文字或任何假UI。')]
ui_base='Use case: illustration-story\nAsset type: RESET UI illustrative background\n横幅16:9精致二维VN场景插画，现代中国校园都市灵异，清晰线条、克制赛璐璐和柔和渐变，低饱和，保持现有美术世界。所有可交互控件与文字由游戏绘制；这张只提供插画。无文字无logo无水印无UI，无摄影无3D无简笔画。'
plan['ui']=[]
for id,name,design in uis:
 d=Path('game/art-sources/chatgpt/ui')/id
 (d/'prompt.txt').write_text(ui_base+'\nScene/backdrop: '+design+'\n')
 (d/'spec.json').write_text(json.dumps({'schema':1,'id':id,'name':name,'kind':'ui-key-visual','canonSources':['docs/ART_DIRECTION.md','game/runtime/experience.css','game/assets/4k/asset-plan.json'],'designProposal':design,'constraints':['Illustrative background only; controls and text remain real runtime UI','1920x1080 runtime; processed 3840x2160 master','No native 4K claim'],'reviewStatus':'UNVERIFIED','native4kClaim':False},ensure_ascii=False,indent=2)+'\n')
 plan['ui'].append({'id':id,'name':name,'kind':'ui','status':'TO_GENERATE','prompt':str(d/'prompt.txt'),'spec':str(d/'spec.json')})
planpath.write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n')
print('Prepared',len(items),'backgrounds covering',len(mapping),'scene mappings and',len(uis),'UI key visuals')
